-- =============================================================================
-- 224_di3_import_rsvps.sql - Dance Infusion #3: first data import + corrections
-- =============================================================================
-- GENERATED by gen224.py from events/dance-infusion/di-03-2026-11/source-files/
--   Dance_Infusion__3_11-4-2026.xlsx  (Zeffy, through 11/4)
--   DanceInfusion3_11-04_guests.csv   (Partiful, through 11/4)
-- Keith's brief of 2026-11-04. Touches DI #3 (slug dance-infusion-3) ONLY;
-- no DI #1 / DI #2 row is written. Every block asserts what it touched.
--
-- Schema (additive):
--   * event_rsvps - an RSVP LAYER. RSVPs are never tickets, attendance or
--     revenue; nothing that computes money or the door reads this table.
--     guest_id = exact full-name match (auto-linked); suggested_guest_id = a
--     partial match waiting for a person to confirm. Never both.
--   * sponsorships.payment_refs - the source keys of payments already applied
--     to a sponsorship, so a re-import of the same Zeffy export can never
--     re-book a sponsor payment as a donation (Savery's $250 sits in Zeffy as
--     "1x Donations").
--
-- Data:
--   Zeffy  - 13 ticket rows / 14 tickets ($25 x11, $40 x3) = $395; Pat Donnelly $50
--            donation; Pulse + Theresa Champion payments -> paid; Patrick Savery's
--            $250 reclassified donation -> sponsor payment. Amy Garcia's FAILED $25
--            is a follow-up task, not revenue.
--   Savery/Martinez Champion is SPLIT into two rows so paid/pending is true:
--            Savery $250 paid (keeps the 4 comps) + Martinez $250 pending.
--   Keith Berkman - new Champion, $500, pending (225 marks it paid), 0 comps.
--   Comps   - Theresa's Terri + Bill (last names unknown - flagged); 5 DJs from
--            Keith (b2b cancelled, 1-2h sets) also written to event_participants;
--            JayJay x2, Amanda Maldonado x1.
--   Partiful - 77 RSVPs, 8 exact links, 9 suggestions.
--   Mailing - ticket buyers: new emails subscribed, all subscribed buyers tagged
--            'di-03-2026-11' + 'dance_infusion' (the DI convention is the event code).
-- =============================================================================

begin;

-- ---------------------------------------------------------------- schema
create table if not exists public.event_rsvps (
  id                 uuid primary key default gen_random_uuid(),
  event_id           uuid not null references public.events(id) on delete cascade,
  source             text not null default 'partiful',
  external_key       text not null,
  name               text not null,
  status             text not null check (status in ('going', 'maybe', 'cant_go', 'interested')),
  rsvp_at            timestamptz,
  invited_by         text,
  plus_one_of        text,
  explore_source     text,
  guest_id           uuid references public.guests(id) on delete set null,
  suggested_guest_id uuid references public.guests(id) on delete set null,
  match_note         text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (event_id, source, external_key),
  check (guest_id is null or suggested_guest_id is null)
);
create index if not exists event_rsvps_event_idx on public.event_rsvps (event_id);
create index if not exists event_rsvps_guest_idx on public.event_rsvps (guest_id);

drop trigger if exists event_rsvps_touch on public.event_rsvps;
create trigger event_rsvps_touch before update on public.event_rsvps
  for each row execute function public.event_control_touch();

alter table public.event_rsvps enable row level security;
drop policy if exists "Admins manage rsvps" on public.event_rsvps;
create policy "Admins manage rsvps" on public.event_rsvps
  for all using (public.is_admin()) with check (public.is_admin());
-- 013's default privileges grant anon; these are names + who invited whom.
revoke all on public.event_rsvps from anon;

alter table public.sponsorships add column if not exists payment_refs text[] not null default '{}';

-- ---------------------------------------------------------------- data
create temp table _z (ext text, name text, email text, label text, tier text, qty int, amount numeric, at timestamptz) on commit drop;
insert into _z values
  ('zeffy:SI2-2146550011-0000060', 'Arthemise Brouillet', 'abrouillet.inf@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-11-04 22:43 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000059', 'Patrick Monahan', 'prm67@cornell.edu', 'Guest List + Sponsorship', '$40 ticket', 1, 40, '2026-11-04 22:27 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000058', 'Robyn Silber', 'rjsilber@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-11-04 21:25 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000057', 'Alec Roslin', 'alecroslin20@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-11-04 17:10 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000056', 'Brianna Totino', 'btotino814@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-11-04 10:49 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000055', 'Jessica Stewart', 'jess.stewart123@gmail.com', 'Guest List + Sponsorship', '$40 ticket', 1, 40, '2026-11-04 10:32 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000054', 'Francisco Alegria', 'fea1985@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-11-04 09:29 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000053/0', 'Aysha Khawaja', 'ayesha.khawaja95@gmail.com', 'Guest List + Sponsorship', '$40 ticket', 1, 40, '2026-10-31 11:42 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000053/1', 'Aysha Khawaja', 'ayesha.khawaja95@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-10-31 11:42 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000052', 'Lauren Pollak', 'lpoll123@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-10-30 15:22 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000051', 'Brianna Weiss', 'brianna.weiss999@gmail.com', 'Guest List', '$25 ticket', 1, 25, '2026-10-30 15:22 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000050', 'Lovely Dumlao', 'lovelydumlao@icloud.com', 'Guest List', '$25 ticket', 1, 25, '2026-10-07 15:34 America/New_York'::timestamptz),
  ('zeffy:SI2-2146550011-0000048', 'Lorena Hunter', 'lorenaragon13@gmail.com', 'Guest List', '$25 ticket', 2, 50, '2026-09-30 19:10 America/New_York'::timestamptz);

do $$
declare
  ev  uuid;
  t25 uuid;  t40 uuid;
  sp_pd uuid; sp_tb uuid; sp_sa uuid; sp_ma uuid; sp_kb uuid;
  a_ma uuid; a_kb uuid; a_em uuid;
  n int;
begin
  select id into ev from public.events where slug = 'dance-infusion-3' and deleted_at is null;
  if ev is null then raise exception 'DI #3 not found'; end if;
  if exists (select 1 from public.ticketing where event_id = ev) then raise exception 'DI #3 already has tickets - 224 already applied?'; end if;
  if exists (select 1 from public.event_participants where event_id = ev) then raise exception 'DI #3 already has a lineup'; end if;

  select id into t25 from public.event_ticket_tiers where event_id = ev and label = '$25 ticket' and price = 25 and to_mission = 25;
  select id into t40 from public.event_ticket_tiers where event_id = ev and label = '$40 ticket' and price = 40 and to_mission = 25;
  if t25 is null or t40 is null then raise exception 'tiers not as seeded by 223'; end if;
  update public.event_ticket_tiers set aliases = array(select distinct unnest(coalesce(aliases, '{}') || array['guest list'])) where id = t25;
  update public.event_ticket_tiers set aliases = array(select distinct unnest(coalesce(aliases, '{}') || array['guest list + sponsorship'])) where id = t40;
  update _z set tier = case tier when '$25 ticket' then t25::text else t40::text end;

  select id into sp_pd from public.sponsorships where event_id = ev and actor_id = 'dc1197e9-caa3-4f69-adfb-c2e01cb79821' and status = 'pending' and cash_amount = 500;
  select id into sp_tb from public.sponsorships where event_id = ev and actor_id = 'a6421b01-1ca2-41f7-a045-e1845667d7b3' and status = 'pending' and cash_amount = 500;
  select id into sp_sa from public.sponsorships where event_id = ev and actor_id = 'd3d26350-6c81-4c89-95e9-384efb7cb363' and status = 'pending' and cash_amount = 500;
  if sp_pd is null or sp_tb is null or sp_sa is null then raise exception 'sponsorships not as seeded by 223'; end if;

  -- ---- Step 1: people (email first, then name; none of the new buyers matches by name)
  insert into public.guests (full_name, email, source)
  select distinct on (z.email) z.name, z.email, 'import:zeffy:di-03-2026-11'
  from _z z
  where not exists (select 1 from public.guests g where lower(g.email) = z.email and g.deleted_at is null)
  order by z.email;
  get diagnostics n = row_count;
  if n <> 9 then raise exception 'expected 9 new buyer guests, got %', n; end if;

  -- tickets (external_id = the page importer's own key, so a re-import dedupes)
  insert into public.ticketing (event_id, guest_id, ticket_type, amount_paid, quantity, source, external_id, purchased_at, tier_id)
  select ev, (select g.id from public.guests g where lower(g.email) = z.email and g.deleted_at is null order by g.created_at limit 1),
         z.label, z.amount, z.qty, 'zeffy', z.ext, z.at, z.tier::uuid
  from _z z;
  get diagnostics n = row_count;
  if n <> 13 then raise exception 'expected 13 ticket rows, got %', n; end if;
  if (select sum(quantity) from public.ticketing where event_id = ev) <> 14
     or (select sum(amount_paid) from public.ticketing where event_id = ev) <> 395
     or exists (select 1 from public.ticketing where event_id = ev and guest_id is null)
  then raise exception 'ticket totals off'; end if;

  -- door rows: one per buyer, party size = their tickets
  insert into public.guest_event_attendance (guest_id, event_id, entry_type, source, ticket_type, quantity, amount_spent, tier_id, purchased_at)
  select t.guest_id, ev, 'ticket', 'zeffy', string_agg(t.ticket_type, ' + ' order by t.external_id), sum(t.quantity), sum(t.amount_paid),
         (array_agg(t.tier_id order by t.external_id desc))[1], min(t.purchased_at)
  from public.ticketing t where t.event_id = ev group by t.guest_id;
  get diagnostics n = row_count;
  if n <> 12 then raise exception 'expected 12 buyer door rows, got %', n; end if;

  insert into public.third_party_donations (event_id, donor_name, amount, payment_processor, date, notes, external_ref)
  values (ev, 'Pat Donnelly', 50, 'Zeffy', '2026-10-23', '1x Donations', 'zeffy:10/23/2026 2:41 PM|pmd55@optonline.net|50');

  -- ---- Step 3: sponsors
  update public.sponsorships set status = 'paid', payment_refs = array['zeffy:SI2-2146550011-0000047'],
         notes = 'Paid via Zeffy 9/17/2026 ($500, card, Ethan Pollak).'
   where id = sp_pd;
  update public.sponsorships set status = 'paid', payment_refs = array['zeffy:SI2-2146550011-0000049'],
         notes = 'Paid via Zeffy 10/7/2026 ($500).'
   where id = sp_tb;
  -- 3a: Savery's $250 was logged in Zeffy as "1x Donations". It is HALF the
  -- Savery/Martinez Champion. Split so each half carries its own status.
  update public.sponsorships set cash_amount = 250, status = 'paid', payment_refs = array['zeffy:10/26/2026 10:18 PM|patrick.savery@gmail.com|250'],
         notes = 'Savery/Martinez Champion ($500 total), Patrick Savery''s half: $250 paid via Zeffy 10/26/2026 (logged there as a donation; reclassified 2026-11-04). The 4 comps + drink package for the whole Champion live on this card. Other half: Dr. Arnaldo Martinez, pending.'
   where id = sp_sa;
  insert into public.actors (kind, display_name, notes) values ('person', 'Arnaldo Martinez', 'Dr. Arnaldo Martinez. DI #3 Savery/Martinez Champion (second half).')
  returning id into a_ma;
  insert into public.sponsorships (event_id, actor_id, tier, cash_amount, entry_tickets, drink_tickets, drink_tickets_tbd, status, notes)
  values (ev, a_ma, 'Champion', 250, 0, 0, false, 'pending',
          'Savery/Martinez Champion ($500 total), Dr. Arnaldo Martinez''s half: $250 pending. Comps + drinks are on the Patrick Savery card.')
  returning id into sp_ma;
  -- 3b: Keith (on the list as a DJ, so 0 comps)
  insert into public.actors (kind, display_name, notes) values ('person', 'Keith Berkman', 'Same person as the DJ actor "Berky". Created for the DI #3 Champion sponsorship.')
  returning id into a_kb;
  insert into public.sponsorships (event_id, actor_id, tier, cash_amount, entry_tickets, drink_tickets, drink_tickets_tbd, status, notes)
  values (ev, a_kb, 'Champion', 500, 0, 0, true, 'pending', 'Not in Zeffy. 0 comps (Keith is on the list as a DJ).')
  returning id into sp_kb;

  -- 3c: Theresa's comps 2 + 3 (she is already comp 1). Last names not in DI #2 data.
  insert into public.guests (full_name, source, notes) values
    ('Terri', 'control-center:224', 'Last name unknown - not in DI #2 data. Theresa Berkman comp (DI #3). Possibly Theresa McGuinness (DI #2 donor)? Confirm with Keith.'),
    ('Bill',  'control-center:224', 'Last name unknown - not in DI #2 data. Theresa Berkman comp (DI #3). Confirm with Keith.');
  insert into public.guest_event_attendance (guest_id, event_id, entry_type, sponsorship_id, quantity, source, ticket_type)
  select id, ev, 'sponsor_comp', sp_tb, 1, 'sponsor', 'Sponsor comp' from public.guests where source = 'control-center:224' and full_name in ('Terri', 'Bill');
  get diagnostics n = row_count;
  if n <> 2 then raise exception 'expected 2 Theresa comps, got %', n; end if;
  if (select count(*) from public.guest_event_attendance where sponsorship_id = sp_tb) <> 3 then raise exception 'Theresa should hold 3 of 3'; end if;
  if (select count(*) from public.guest_event_attendance where sponsorship_id = sp_sa) <> 3 then raise exception 'Savery comps changed'; end if;

  -- ---- Step 4: DJs (b2b cancelled; each plays their own slot) + Keith's comps
  insert into public.actors (kind, display_name, notes) values ('person', 'Emmy Adele', 'DJ, DI #3 (6:30-8:30 PM).')
  returning id into a_em;
  insert into public.guests (full_name, email, actor_id, source) values
    ('Rainbow TuTu', 'rainbowtutudj@gmail.com', 'ad8bbe67-7e50-42c5-b39a-f2f6d46c1823', 'control-center:224'),
    ('Emmy Adele', null, a_em, 'control-center:224'),
    ('JayJay', null, null, 'control-center:224'),
    ('Amanda Maldonado', null, null, 'control-center:224');

  insert into public.event_participants (event_id, actor_id, role, roles, bill_order, set_start, set_end, notes) values
    (ev, '0fcf0af5-2ea6-4de1-8e34-c873ea3a40bb', 'dj', '{dj}', 1, '2026-11-14 15:00 America/New_York', '2026-11-14 16:00 America/New_York', 'Flier billed Miss Vee b2b Rainbow TuTu; b2b cancelled.'),
    (ev, 'ad8bbe67-7e50-42c5-b39a-f2f6d46c1823', 'dj', '{dj}', 2, '2026-11-14 16:00 America/New_York', '2026-11-14 17:00 America/New_York', 'Flier billed Miss Vee b2b Rainbow TuTu; b2b cancelled.'),
    (ev, '09939421-2095-4151-b943-2d943bf83615', 'dj', '{dj}', 3, '2026-11-14 17:00 America/New_York', '2026-11-14 18:30 America/New_York', null),
    (ev, a_em,                                   'dj', '{dj}', 4, '2026-11-14 18:30 America/New_York', '2026-11-14 20:30 America/New_York', null),
    (ev, '400d9160-327d-461a-bf26-1cd9a9723372', 'dj', '{dj}', 5, '2026-11-14 20:30 America/New_York', '2026-11-14 22:00 America/New_York', null);

  insert into public.guest_event_attendance (guest_id, event_id, entry_type, quantity, source, ticket_type, notes) values
    ('7a425ab8-ec15-4514-bc32-d79d9eff93ea', ev, 'dj', 1, 'manual', 'DJ', 'Miss Vee - 3:00-4:00 PM. Drink tickets TBD.'),
    ((select id from public.guests where source = 'control-center:224' and full_name = 'Rainbow TuTu'), ev, 'dj', 1, 'manual', 'DJ', 'Rainbow TuTu - 4:00-5:00 PM. Drink tickets TBD.'),
    ('bd39d389-a3a7-4102-bbca-5d0f4d7ba195', ev, 'dj', 1, 'manual', 'DJ', 'Berky (Keith Berkman) - 5:00-6:30 PM. Drink tickets TBD. Also a Champion sponsor (0 comps).'),
    ((select id from public.guests where source = 'control-center:224' and full_name = 'Emmy Adele'), ev, 'dj', 1, 'manual', 'DJ', 'Emmy Adele - 6:30-8:30 PM. Drink tickets TBD.'),
    ('b245be34-13b7-4b82-9c88-52de5f8b43f5', ev, 'dj', 1, 'manual', 'DJ', 'KRNeY (Martin Kearney) - 8:30-10:00 PM. Drink tickets TBD.'),
    ((select id from public.guests where source = 'control-center:224' and full_name = 'JayJay'), ev, 'comp', 2, 'manual', 'Comp', 'Comp from Keith - 2 entries (as DI #2).'),
    ((select id from public.guests where source = 'control-center:224' and full_name = 'Amanda Maldonado'), ev, 'comp', 1, 'manual', 'Comp', 'Comp from Keith - 1 entry (as DI #2). DI #2 also gave her 2 drink tickets; not carried over - confirm.');
  get diagnostics n = row_count;
  if n <> 7 then raise exception 'expected 7 DJ/comp rows, got %', n; end if;

  -- ---- Amy Garcia: failed payment = follow-up, not revenue
  insert into public.tasks (event_id, title, description, status, priority, source)
  values (ev, 'Follow up: Amy Garcia''s Zeffy payment failed',
          'Zeffy shows a FAILED $25 card payment on 10/27/2026 9:23 PM (teamchicago@comcast.net). Not counted as a ticket or revenue. Ask her to retry.',
          'todo', 'medium', 'manual');

  -- ---- mailing: ticket buyers (never donors/sponsors), never re-subscribe anyone
  insert into public.subscribers (email, full_name, status, source, confirmed_at, guest_id)
  select distinct on (z.email) z.email, z.name, 'subscribed', 'event-import:di-03-2026-11', now(),
         (select g.id from public.guests g where lower(g.email) = z.email and g.deleted_at is null order by g.created_at limit 1)
  from _z z
  where not exists (select 1 from public.subscribers s where lower(s.email) = z.email)
    and not exists (select 1 from public.guests g where lower(g.email) = z.email and g.opted_in_mailing = false and g.deleted_at is null and g.source not like 'import:zeffy:di-03-2026-11')
  order by z.email;

  insert into public.subscriber_segments (subscriber_id, segment)
  select s.id, seg.v
  from public.subscribers s
  cross join (values ('di-03-2026-11'), ('dance_infusion')) seg(v)
  where s.status = 'subscribed' and lower(s.email) in (select email from _z)
    and not exists (select 1 from public.subscriber_segments x where x.subscriber_id = s.id and x.segment = seg.v);
end $$;

-- ---------------------------------------------------------------- Partiful RSVPs
insert into public.event_rsvps (event_id, external_key, name, status, rsvp_at, invited_by, plus_one_of, explore_source, guest_id, suggested_guest_id, match_note)
select (select id from public.events where slug = 'dance-infusion-3'), v.*
from (values
  ('partiful:aaron edmiston', 'Aaron Edmiston', 'cant_go', '2026-11-04 12:20:04-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:alexey', 'Alexey', 'going', '2026-10-30 16:28:06-04:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
