  ('partiful:amanda maldonado', 'Amanda Maldonado', 'maybe', '2026-10-03 05:17:26-04:00'::timestamptz, null, null, null, (select id from public.guests where source = 'control-center:224' and full_name = 'Amanda Maldonado'), null, null),
