  ('partiful:amanda maldonado''s +1#2', 'Amanda Maldonado''s +1', 'maybe', '2026-10-03 05:17:26-04:00'::timestamptz, 'Amanda Maldonado', 'Amanda Maldonado', null, null, null, null),
