  ('partiful:aubrey', 'Aubrey', 'maybe', '2026-11-03 15:01:05-05:00'::timestamptz, null, null, null, null, null, null),
  ('partiful:candice zeng', 'Candice Zeng', 'cant_go', '2026-11-03 19:58:50-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:daniel x. bandong', 'Daniel X. Bandong', 'maybe', '2026-11-04 21:38:40-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:desirée duff', 'Desirée Duff', 'cant_go', '2026-11-03 16:33:56-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:dozenfingers photography', 'DozenFingers Photography', 'maybe', '2026-08-13 16:20:51-04:00'::timestamptz, null, null, null, null, null, null),
  ('partiful:ella geida', 'Ella Geida', 'going', '2026-11-03 16:37:05-05:00'::timestamptz, null, null, 'Explore', null, null, null),
  ('partiful:erica romoff', 'Erica Romoff', 'maybe', '2026-10-20 05:37:15-04:00'::timestamptz, null, null, null, 'a61b9c8f-3758-4be3-ba77-88a15db305b7'::uuid, null, null),
  ('partiful:joshua romoff', 'Joshua Romoff', 'maybe', '2026-10-20 05:37:15-04:00'::timestamptz, 'Erica Romoff', 'Erica Romoff', null, null, null, null),
  ('partiful:joe cambria', 'Joe Cambria', 'maybe', '2026-10-20 05:37:15-04:00'::timestamptz, 'Erica Romoff', 'Erica Romoff', null, null, null, null),
  ('partiful:ericka', 'Ericka', 'maybe', '2026-11-03 16:19:51-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:ethan b', 'Ethan B', 'going', '2026-11-03 16:15:27-05:00'::timestamptz, 'Jessica Kenny', null, null, null, null, null),
  ('partiful:ethan pollak', 'ethan pollak', 'going', '2026-08-31 18:05:07-04:00'::timestamptz, null, null, null, 'a9404baa-18a5-4d3e-8bf5-23747a222cde'::uuid, null, null),
