do $$
declare ev uuid := (select id from public.events where slug = 'dance-infusion-3');
begin
  if (select count(*) from public.event_rsvps where event_id = ev) <> 77 then raise exception 'expected 77 RSVPs'; end if;
  if (select count(*) from public.event_rsvps where event_id = ev and guest_id is not null) <> 8 then raise exception 'expected 8 exact links'; end if;
  if (select count(*) from public.event_rsvps where event_id = ev and match_note is not null) <> 9 then raise exception 'expected 9 suggestions'; end if;
  if (select count(*) from public.event_rsvps where event_id = ev and suggested_guest_id is not null) <> 8 then raise exception 'a suggested guest did not resolve'; end if;
  if (select sum(cash_amount) from public.sponsorships where event_id = ev and status <> 'cancelled') <> 2000 then raise exception 'committed <> 2000'; end if;
  if (select sum(cash_amount) from public.sponsorships where event_id = ev and status = 'paid') <> 1250 then raise exception 'received <> 1250'; end if;
end $$;

commit;
